  "knowledge": "Social Support Level",
  "description": "Illustrates the value of social support levels.",
  "definition": "Ranges from Weak to Strong. Weak indicates minimal support, Limited indicates some support, Adequate indicates good support, and Strong indicates robust support."
}

{
  "id": 35,
  "knowledge": "Socio-Environmental Support Index (SESI)",
  "description": "Computes a composite index reflecting the quality of the patient's social environment and the facility's resource context.",
  "definition": "SESI = \frac{\text{Average Social Support Effectiveness} + \text{Facility Resource Adequacy Index}}{2}"
}

{
  "id": 8,
  "knowledge": "Social Support Effectiveness (SSE)",
  "description": "Evaluates the effectiveness of social support based on social support level and relationship quality.",
  "definition": "SSE = \text{The average of the sum of two scores: a social support score (Strong=3, Adequate=2, Limited=1, Weak=0) and a relationship quality score (Good=3, Fair=2, Poor=1, Conflicted=0).}"
}

{
  "id": 60,
  "knowledge": "Correlation Between Resource Adequacy and Adherence (CRAA)",
  "description": "Measures the correlation between individual facility resource adequacy scores and treatment adherence rates.",
  "definition": "CRAA = \text{CORRELATION}(\text{facility resource score}, \text{facility treatment adherence rate})"
}

{
  "id": 24,
  "knowledge": "Community Resources",
  "description": "Illustrates the value of community resource availability.",
  "definition": "Ranges from Limited to Comprehensive/Extensive. Limited indicates few resources, Adequate indicates sufficient resources, and Comprehensive/Extensive indicates robust resources."
}

{
  "id": 26,
  "knowledge": "Treatment Adherence",
  "description": "Illustrates the value of treatment adherence levels.",
  "definition": "Ranges from Non-compliant to High/Compliant. Non-compliant indicates no adherence, Low indicates occasional adherence, Medium indicates regular adherence, and High/Compliant indicates consistent adherence."
}

{
  "id": 39,
  "knowledge": "Support System Pressure Index (SSPI)",
  "description": "Index assessing the pressure on support systems based on crisis frequency relative to social support effectiveness.",
  "definition": "SSPI = \frac{\text{Crisis Intervention Frequency}}{\text{Average Social Support Effectiveness} + 1}"
}

{
  "id": 44,
  "knowledge": "Well-Resourced High-Support Environment",
  "description": "Identifies facilities that are well-resourced and serve a patient population with generally high levels of social support effectiveness.",
  "definition": "A facility where the Facility Resource Adequacy Index is 2.0 or greater and the average Social Support Effectiveness score of its patients is 4.5 or greater."
}

{
  "id": 34,
  "knowledge": "Resource-Demand Differential (RDD)",
  "description": "Measures the potential gap between average patient functional needs and available facility resources.",
  "definition": "RDD = \text{Patient Functional Impairment Score} - \text{Facility Resource Adequacy Index}"
}

